  useFrame((state) => {
    const t = state.clock.getElapsedTime();
    // Scroll interaction
    const scrollY = window.scrollY;
    const scrollProgress = scrollY * 0.0005;

    if (groupRef.current) {
      // General group rotation based on scroll
      groupRef.current.rotation.y = THREE.MathUtils.lerp(groupRef.current.rotation.y, scrollProgress, 0.05);
      groupRef.current.rotation.x = THREE.MathUtils.lerp(groupRef.current.rotation.x, scrollProgress * 0.5, 0.05);
    }

    if (ring1Ref.current) {
      ring1Ref.current.rotation.z = t * 0.1 + scrollProgress;
      ring1Ref.current.rotation.x = Math.sin(t * 0.2) * 0.2;
    }

    if (ring2Ref.current) {
      ring2Ref.current.rotation.z = -t * 0.15 - scrollProgress;
      ring2Ref.current.rotation.y = Math.cos(t * 0.3) * 0.2;
    }

    if (coreRef.current) {
      coreRef.current.rotation.y = t * 0.2;
      coreRef.current.rotation.z = t * 0.1;
    }

    if(floatingGeoRef.current) {
      floatingGeoRef.current.rotation.y = scrollProgress * 2;
    }
  });

  // Material constant for the "blueprint" look
  const wireframeMaterial = new THREE.MeshBasicMaterial({
    color: '#475569', // Slate-600 (cool gray)
    wireframe: true,
    transparent: true,
    opacity: 0.15,
  });

  const accentMaterial = new THREE.MeshBasicMaterial({
    color: '#780000', // Maroon
    wireframe: true,
    transparent: true,
    opacity: 0.2,
  });

  return (
    <group ref={groupRef} position={[2, 0, 0]} scale={1.5}>
      {/* Primary Large Ring */}
      <Torus ref={ring1Ref} args={[3.5, 0.02, 16, 100]} material={wireframeMaterial} />

      {/* Secondary Angled Ring */}
      <Torus ref={ring2Ref} args={[2.8, 0.02, 16, 80]} rotation={[1, 0, 0]} material={wireframeMaterial} />

      {/* The Core Mechanism */}
      <Float speed={2} rotationIntensity={0.5} floatIntensity={0.5}>
         <Icosahedron ref={coreRef} args={[1, 1]} material={wireframeMaterial} />
         <Icosahedron args={[0.8, 0]} material={accentMaterial} />
      </Float>

      {/* Floating Geometric Constellations */}
      <group ref={floatingGeoRef}>
        <Float speed={1.5} rotationIntensity={1} floatIntensity={1}>
           <Octahedron position={[-4, 3, -2]} args={[0.5]} material={wireframeMaterial} />
        </Float>
        <Float speed={1} rotationIntensity={2} floatIntensity={1}>
           <Octahedron position={[-3, -4, 2]} args={[0.3]} material={wireframeMaterial} />
        </Float>
      </group>
    </group>
  );
};

const Background3D: React.FC = () => {
  return (
    <div className="fixed top-0 left-0 w-full h-screen z-0 pointer-events-none opacity-60">
      <Canvas camera={{ position: [0, 0, 8], fov: 45 }}>
        <fog attach="fog" args={['#1B263B', 5, 15]} />
        <ambientLight intensity={0.5} />
        <Mechanism />
      </Canvas>
      {/* Vignette overlay to fade edges */}
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_0%,#1B263B_100%)] pointer-events-none" />
